/*
 * A126258  Triangle generated by Pascal's rule with left diagonal =
 *          [1,0,2,0,3,0,4,...] (A000027 with interpolated zeros) and right
 *          diagonal = [1,1,1,1,1,...].
 * https://oeis.org/A126258
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl, easy
 * Formula:   a(n) is the n‑th element (row‑wise) of the triangle generated by
 *            Pascal's rule with left diagonal [1,0,2,0,3,0,4,…] (A000027 with
 *            interpolated zeros) and right diagonal [1,1,1,1,1,…]. The
 *            triangle T satisfies T(0,0) = 1 T(n,0) = (n%2==0 ? n/2+1 : 0)
 *            (left diagonal) T(n,n) = 1 (right diagonal) T(n...
 * Range:     u8 n <= 69, u16 n <= 77, u32 n <= 77, u64 n <= 77, u128 n <= 77,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static seq_t **tri = NULL;      /* array of pointers to each row          */
static size_t max_row = 0;     /* number of rows that have been built     */

/* Build rows of the triangle up to and including `need`.  Rows are stored
   one element per entry; memory is allocated on first use and grows only
   as needed.  All values are of type seq_t.  */
static void ensure_tri_rows(idx_t need)
{
    while (max_row <= need) {
        size_t len = max_row + 1;           /* number of elements in new row   */
        seq_t *row = (seq_t*)malloc(len * sizeof(seq_t));
        if (!row) abort();                  /* out of memory */
        if (max_row == 0) {
            row[0] = (seq_t)1;              /* T(0,0) = 1                      */
        } else {
            /* left diagonal */
            if ((max_row & 1ULL) == 0)
                row[0] = (seq_t)(max_row / 2 + 1);
            else
                row[0] = (seq_t)0;
            /* right diagonal */
            row[max_row] = (seq_t)1;

            /* interior cells via Pascal's rule */
            seq_t *prev = tri[max_row - 1];
            for (size_t k = 1; k < max_row; ++k)
                row[k] = prev[k] + prev[k - 1];
        }

        /* enlarge the array of row pointers */
        tri = (seq_t**)realloc(tri, (max_row + 1) * sizeof(seq_t*));
        if (!tri) abort();                  /* out of memory */
        tri[max_row] = row;
        ++max_row;
    }
}

/* Find the row index r such that r*(r+1)/2 <= n < (r+1)*(r+2)/2.  */
static idx_t row_of(idx_t n)
{
    idx_t lo = 0, hi = 1;
    /* Expand hi until the range covers n.  Use 128‑bit arithmetic to avoid overflow.  */
    while ((__int128)hi * (hi + 1) / 2 <= n) hi <<= 1;
    while (lo + 1 < hi) {
        idx_t mid = lo + ((hi - lo) >> 1);
        if ((__int128)mid * (mid + 1) / 2 <= n)
            lo = mid;
        else
            hi = mid;
    }
    return lo;
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)1;         /* a(0) = 1 */

    idx_t r = row_of(n);
    __int128 start128 = (__int128)r * (r + 1) / 2;
    idx_t start = (idx_t)start128;
    idx_t k = n - start;                  /* column index in row r */

    ensure_tri_rows(r);
    return tri[r][k];
}
